TREAK","comparison":"UNSUPPORTED","achievement_key":"APP_BASE_MONTHLY_IMPORT_STREAK_1","tier":1,"target":1,"xp":50,"title":"Monthly Base Check-in","description":"Provide at least one valid base import in consecutive months.","rarity":"common"},{"family_key":"APP_BASE_MONTHLY_IMPORT_STREAK","scope":"player","category":"clashpanel_workflow","metric":"spec:APP_BASE_MONTHLY_IMPORT_STREAK","comparison":"UNSUPPORTED","achievement_key":"APP_BASE_MONTHLY_IMPORT_STREAK_2","tier":2,"target":1,"xp":100,"title":"Monthly Base Check-in","description":"Provide at least one valid base import in consecutive months.","rarity":"uncommon"},{"family_key":"APP_BASE_MONTHLY_IMPORT_STREAK","scope":"player","category":"clashpanel_workflow","metric":"spec:APP_BASE_MONTHLY_IMPORT_STREAK","comparison":"UNSUPPORTED","achievement_key":"APP_BASE_MONTHLY_IMPORT_STREAK_3","tier":3,"target":1,"xp":200,"title":"Monthly Base Check-in","description":"Provide at least one valid base import in consecutive months.","rarity":"rare"},{"family_key":"APP_BASE_MONTHLY_IMPORT_STREAK","scope":"player","category":"clashpanel_workflow","metric":"spec:APP_BASE_MONTHLY_IMPORT_STREAK","comparison":"UNSUPPORTED","achievement_key":"APP_BASE_MONTHLY_IMPORT_STREAK_4","tier":4,"target":1,"xp":400,"title":"Monthly Base Check-in","description":"Provide at least one valid base import in consecutive months.","rarity":"epic"},{"family_key":"DYN_OFFICIAL_ACHIEVEMENT","scope":"player","category":"dynamic_official_achievements","metric":"spec:DYN_OFFICIAL_ACHIEVEMENT","comparison":"UNSUPPORTED","achievement_key":"DYN_OFFICIAL_ACHIEVEMENT_1","tier":1,"target":1,"xp":100,"title":"Official Achievement Mastery (dynamic template)","description":"Generate one ClashPanel badge for every official achievement whose value reaches its target. The actual badge ID must be a stable hash of the official achievement name and village.","rarity":"uncommon"}]$catalog$::jsonb) as seed(
    family_key text, scope text, category text, metric text, comparison text,
    achievement_key text, tier smallint, target bigint, xp integer,
    title text, description text, rarity text
);

insert into public.achievement_families
    (family_key, scope, category, metric, title, description, comparison)
select distinct on (family_key)
    family_key, scope, category, metric, title, description, comparison
from compact_achievement_catalog_seed
order by family_key, tier
on conflict (family_key) do update
set scope = excluded.scope,
    category = excluded.category,
    metric = excluded.metric,
    title = excluded.title,
    description = excluded.description,
    comparison = excluded.comparison;

insert into public.achievement_definitions
    (family_id, achievement_key, tier, target, xp, rarity)
select f.family_id, s.achievement_key, s.tier, s.target, s.xp, s.rarity
from compact_achievement_catalog_seed s
join public.achievement_families f on f.family_key = s.family_key
order by f.family_id, s.tier
on conflict (achievement_key) do update
set family_id = excluded.family_id,
    tier = excluded.tier,
    target = excluded.target,
    xp = excluded.xp,
    rarity = excluded.rarity;

do $catalog_parity$
begin
    if (select count(distinct family_key) from compact_achievement_catalog_seed) <> 340 then
        raise exception 'Compact achievement catalog family count mismatch';
    end if;
    if (select count(*) from compact_achievement_catalog_seed) <> 1331 then
        raise exception 'Compact achievement catalog tier count mismatch';
    end if;
    if exists (
        select 1
        from compact_achievement_catalog_seed s
        left join public.achievement_families f using (family_key)
        left join public.achievement_definitions d
          on d.family_id = f.family_id and d.achievement_key = s.achievement_key
        where f.family_id is null or d.achievement_id is null
           or f.comparison <> s.comparison or d.tier <> s.tier
           or d.target <> s.target or d.xp <> s.xp
    ) then
        raise exception 'Compact achievement catalog seed parity failed';
    end if;
end;
$catalog_parity$;

drop table compact_achievement_catalog_seed;
